                background-color: #2980b9;
            }
        """)
        msg.exec_()

class MainWindow(QMainWindow):
    """主窗口 - 优化版"""

    def __init__(self, user_role, username):
        super().__init__()
        self.user_role = user_role
        self.username = username
        self.db_manager = DatabaseManager()

        self.init_ui()
        self.showMaximized()

    def init_ui(self):
        # 窗口设置
        self.setWindowTitle(f'向阳厂数据管理系统 - 当前用户: {self.username}({self.user_role})')

        # 设置应用图标（如果有的话）
        # self.setWindowIcon(QIcon(':/icons/factory.png'))

        # 设置全局样式
        self.setStyleSheet("""
            QMainWindow {
                background-color: #f5f6fa;
            }
