                color: white;
                padding: 5px;
            }
        """)

        # 中央部件
        central_widget = QWidget()
        main_layout = QVBoxLayout()
        main_layout.setContentsMargins(15, 15, 15, 15)
        main_layout.setSpacing(15)

        # ========== 顶部工具栏 ==========
        toolbar = QWidget()
        toolbar.setFixedHeight(60)
        toolbar.setStyleSheet("""
            QWidget {
                background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
                    stop:0 #3498db, stop:1 #2980b9);
                border-radius: 10px;
            }
        """)

        toolbar_layout = QHBoxLayout()
        toolbar_layout.setContentsMargins(20, 0, 20, 0)

        # 左侧欢迎信息
        welcome_container = QWidget()
        welcome_layout = QHBoxLayout()
        welcome_layout.setContentsMargins(0, 0, 0, 0)
        welcome_layout.setSpacing(10)

        # 用户头像图标
        avatar = QLabel('👤')
        avatar.setFont(QFont('Segoe UI Emoji', 20))
        avatar.setStyleSheet("color: white; background: transparent;")
        welcome_layout.addWidget(avatar)

        # 欢迎文本
        welcome_text = QLabel(f'欢迎回来，{self.username}')
        welcome_text.setFont(QFont('Microsoft YaHei', 12, QFont.Bold))
        welcome_text.setStyleSheet("color: white; background: transparent;")
        welcome_layout.addWidget(welcome_text)

        # 角色标签
        role_badge = QLabel(self.user_role)
