                font-size: 12px;
            }
            QPushButton:hover {
                background: rgba(255, 255, 255, 0.3);
            }
        """)
        refresh_btn.clicked.connect(self.refresh_data)

        # 退出按钮
        logout_btn = QPushButton('🚪 退出')
        logout_btn.setCursor(Qt.PointingHandCursor)
        logout_btn.setStyleSheet("""
