        avatar.setFont(QFont('Segoe UI Emoji', 20))
        avatar.setStyleSheet("color: white; background: transparent;")
        welcome_layout.addWidget(avatar)

        # 欢迎文本
        welcome_text = QLabel(f'欢迎回来，{self.username}')
        welcome_text.setFont(QFont('Microsoft YaHei', 12, QFont.Bold))
        welcome_text.setStyleSheet("color: white; background: transparent;")
        welcome_layout.addWidget(welcome_text)

        # 角色标签
        role_badge = QLabel(self.user_role)
        role_badge.setFixedHeight(25)
        role_badge.setFixedWidth(80)
        role_badge.setAlignment(Qt.AlignCenter)
        role_badge.setStyleSheet("""
            QLabel {
                background: rgba(255, 255, 255, 0.3);
                color: white;
                border-radius: 12px;
                font-size: 11px;
                font-weight: bold;
                border: 1px solid rgba(255, 255, 255, 0.5);
            }
        """)
        welcome_layout.addWidget(role_badge)

        welcome_container.setLayout(welcome_layout)
        toolbar_layout.addWidget(welcome_container)

        toolbar_layout.addStretch()

        # 右侧快捷按钮
        quick_actions = QWidget()
        quick_layout = QHBoxLayout()
        quick_layout.setSpacing(10)
        quick_layout.setContentsMargins(0, 0, 0, 0)

        # 刷新按钮
        refresh_btn = QPushButton('🔄 刷新')
        refresh_btn.setCursor(Qt.PointingHandCursor)
        refresh_btn.setStyleSheet("""
            QPushButton {
                background: rgba(255, 255, 255, 0.2);
                color: white;
                border: 1px solid rgba(255, 255, 255, 0.3);
                border-radius: 5px;
                padding: 8px 15px;
                font-size: 12px;
            }
            QPushButton:hover {
                background: rgba(255, 255, 255, 0.3);
            }
        """)
        refresh_btn.clicked.connect(self.refresh_data)

        # 退出按钮
        logout_btn = QPushButton('🚪 退出')
        logout_btn.setCursor(Qt.PointingHandCursor)
        logout_btn.setStyleSheet("""
            QPushButton {
                background: rgba(255, 255, 255, 0.2);
                color: white;
                border: 1px solid rgba(255, 255, 255, 0.3);
                border-radius: 5px;
                padding: 8px 15px;
                font-size: 12px;
            }
            QPushButton:hover {
                background: #e74c3c;
            }
        """)
        logout_btn.clicked.connect(self.logout)

        quick_layout.addWidget(refresh_btn)
        quick_layout.addWidget(logout_btn)
        quick_actions.setLayout(quick_layout)

        toolbar_layout.addWidget(quick_actions)
        toolbar.setLayout(toolbar_layout)

        main_layout.addWidget(toolbar)

        # ========== 主要内容区域 ==========
        content_widget = QWidget()
        content_layout = QVBoxLayout()
        content_layout.setContentsMargins(0, 0, 0, 0)
        content_layout.setSpacing(15)

        # 标签页
        tab_widget = QTabWidget()
        tab_widget.setDocumentMode(True)  # 现代风格
        tab_widget.tabBar().setExpanding(True)  # 标签等宽

        # 货品加工收发标签页
        goods_tab = GoodsProcessingTab(self.db_manager, self.user_role, self.username)
        tab_widget.addTab(goods_tab, '📦 货品加工收发')

        # 工资核算标签页
        wage_tab = WageCalculationTab(self.db_manager, self.user_role, self.username)
        tab_widget.addTab(wage_tab, '💰 工资核算')

        # 客户结算货款（预留）
        if self.user_role == '财务':
            customer_tab = QWidget()
            # 初始化客户结算标签页
            tab_widget.addTab(customer_tab, '🤝 客户结算')

        # 利润核算（预留）
        if self.user_role == '财务':
            profit_tab = QWidget()
            # 初始化利润核算标签页
            tab_widget.addTab(profit_tab, '📊 利润核算')

        content_layout.addWidget(tab_widget)

        # ========== 底部状态栏 ==========
        status_bar = QStatusBar()
        status_bar.setFixedHeight(35)
        status_bar.showMessage(f'当前时间: {QDateTime.currentDateTime().toString("yyyy-MM-dd hh:mm:ss")} | 数据状态: 已连接')

        # 添加数据库状态指示器
        db_status = QLabel('● 数据库正常')
        db_status.setStyleSheet("color: #2ecc71; font-weight: bold;")
        status_bar.addPermanentWidget(db_status)

        self.setStatusBar(status_bar)

        content_widget.setLayout(content_layout)
        main_layout.addWidget(content_widget)

        central_widget.setLayout(main_layout)
        self.setCentralWidget(central_widget)

        # 定时更新状态栏时间
        self.timer = QTimer()
        self.timer.timeout.connect(self.update_status_time)
        self.timer.start(1000)

    def update_status_time(self):
        """更新状态栏时间"""
        current_time = QDateTime.currentDateTime().toString("yyyy-MM-dd hh:mm:ss")
        self.statusBar().showMessage(f'当前时间: {current_time} | 数据状态: 已连接')

    def refresh_data(self):
        """刷新数据"""
        # 获取当前活动的标签页
        current_tab = self.centralWidget().findChild(QTabWidget).currentWidget()
        if hasattr(current_tab, 'refresh'):
            current_tab.refresh()
            QMessageBox.information(self, '提示', '数据刷新成功！')

    def logout(self):
        """退出登录"""
        reply = QMessageBox.question(
            self, 
            '确认退出', 
            '确定要退出登录吗？',
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No
        )

        if reply == QMessageBox.Yes:
            self.db_manager.close()
            # 返回登录界面
            self.close()

    def closeEvent(self, event):
        """关闭事件"""
        self.db_manager.close()
        event.accept()

def main():
    app = QApplication(sys.argv)

    # 设置应用样式
    app.setStyle('Fusion')

    # 创建数据库管理器（使用正确的数据库路径）
    db_path = get_database_path()
    db_manager = DatabaseManager(db_path)

    # 显示登录对话框
    login_dialog = LoginDialog(db_manager)

    if login_dialog.exec_() == QDialog.Accepted:
        # 创建主窗口
        main_window = MainWindow(login_dialog.user_role, login_dialog.username)
        main_window.show()

        sys.exit(app.exec_())
    else:
        sys.exit(0)


if __name__ == '__main__':
    main()

