        status_bar = QStatusBar()
        status_bar.setFixedHeight(35)
        status_bar.showMessage(f'当前时间: {QDateTime.currentDateTime().toString("yyyy-MM-dd hh:mm:ss")} | 数据状态: 已连接')

        # 添加数据库状态指示器
        db_status = QLabel('● 数据库正常')
        db_status.setStyleSheet("color: #2ecc71; font-weight: bold;")
        status_bar.addPermanentWidget(db_status)

        self.setStatusBar(status_bar)

        content_widget.setLayout(content_layout)
        main_layout.addWidget(content_widget)

        central_widget.setLayout(main_layout)
        self.setCentralWidget(central_widget)

        # 定时更新状态栏时间
        self.timer = QTimer()
        self.timer.timeout.connect(self.update_status_time)
        self.timer.start(1000)

    def update_status_time(self):
        """更新状态栏时间"""
        current_time = QDateTime.currentDateTime().toString("yyyy-MM-dd hh:mm:ss")
        self.statusBar().showMessage(f'当前时间: {current_time} | 数据状态: 已连接')

    def refresh_data(self):
        """刷新数据"""
        # 获取当前活动的标签页
        current_tab = self.centralWidget().findChild(QTabWidget).currentWidget()
        if hasattr(current_tab, 'refresh'):
            current_tab.refresh()
            QMessageBox.information(self, '提示', '数据刷新成功！')

    def logout(self):
        """退出登录"""
        reply = QMessageBox.question(
            self, 
            '确认退出', 
            '确定要退出登录吗？',
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No
        )

        if reply == QMessageBox.Yes:
            self.db_manager.close()
            # 返回登录界面
            self.close()

    def closeEvent(self, event):
        """关闭事件"""
        self.db_manager.close()
        event.accept()

def main():
    app = QApplication(sys.argv)

    # 设置应用样式
    app.setStyle('Fusion')

    # 创建数据库管理器（使用正确的数据库路径）
    db_path = get_database_path()
    db_manager = DatabaseManager(db_path)

    # 显示登录对话框
    login_dialog = LoginDialog(db_manager)

    if login_dialog.exec_() == QDialog.Accepted:
        # 创建主窗口
        main_window = MainWindow(login_dialog.user_role, login_dialog.username)
        main_window.show()

        sys.exit(app.exec_())
    else:
        sys.exit(0)


if __name__ == '__main__':
    main()
